{
  "title": "九尾狐的考验",
  "scene": "你穿越了一片茂密的森林，来到了一座古老的部落前。部落中央的石碑上刻着关于九尾狐的传说，称其为智慧与狡猾的化身。石碑旁有一块较小的石头，上面刻着一行字：‘智者不轻信，勇者不轻动’。部落的入口被一道复杂的机关门阻挡，旁边有一个年轻的部落成员，似乎正焦急地等待着什么。",
  "goal": "找到打开机关门的方法，进入部落。",
  "clue": "石碑旁的小石头",
  "choices": [
    {
      "id": "A",
      "text": "询问年轻部落成员",
      "outcome": "年轻部落成员告诉你，九尾狐考验来访者的智慧，只有正确回答三个谜题，机关门才会打开。你决定先试着解开谜题。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "直接尝试破解机关门",
      "outcome": "你尝试用各种方法破解机关门，但都失败了。门上突然显现出一行字：‘智者不轻信，勇者不轻动’。你意识到自己可能忽略了什么重要的信息。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "研究石碑旁的小石头",
      "outcome": "你仔细研究了石碑旁的小石头，发现上面的刻字实际上是一个提示。三个谜题的答案就隐藏在石碑的传说中。你用这些答案成功打开了机关门，进入了部落。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
